class GSLMatrix:
    def __init__(self, rows, cols):
        self.matrix = gsl.gsl_matrix_alloc(rows, cols)

    def free(self):
        gsl.gsl_matrix_free(self.matrix)

    def __str__(self):
        return str(numpy.array(self.matrix))

    @staticmethod
    def from_numpy(np_array):
        gsl_matrix = gsl.gsl_matrix_alloc(np_array.shape[0], np_array.shape[1])
        for i in range(np_array.shape[0]):
            for j in range(np_array.shape[1]):
                gsl_matrix[i, j] = np_array[i, j]
        return GSLMatrix(np_array.shape[0], np_array.shape[1])

def numpy_to_gsl_matrix(np_array):
    return GSLMatrix.from_numpy(np_array)

def gsl_matrix_to_numpy(gsl_matrix):
    return numpy.array(gsl_matrix).tolist()


def compute_covariance(jacobian, epsrel, cov_dim):
    assert isinstance(jacobian, numpy.ndarray), "Jacobian must be a NumPy array"
    assert jacobian.ndim == 2, "Jacobian must be a 2D array"
    assert epsrel >= 0, "Relative error tolerance must be non-negative"
    assert cov_dim > 0, "Covariance dimension must be positive"

    gsl_jacobian = numpy_to_gsl_matrix(jacobian)
    cov_mat = gsl.gsl_multifit_covar(gsl_jacobian, epsrel)
    return gsl_matrix_to_numpy(cov_mat)


