class gsl_complex(ctypes.Structure):
    _fields_ =
        ['real', 'imag',]

class gsl_vector_complex(ctypes.Structure):
    _fields_ = ['size', 'data',]

class gsl_matrix_complex(ctypes.Structure):
    _fields_ = ['size1', 'size2', 'data',]

def numpy_to_gsl_matrix_complex(np_array):
    shape = np_array.shape
    rows, cols = shape
    data = (gsl_complex * (rows * cols))()
    for i in range(rows):
        for j in range(cols):
            data[i * cols + j].real = np_array[i, j].real
            data[i * cols + j].imag = np_array[i, j].imag
    return gsl_matrix_complex(rows, cols, data)

def numpy_to_gsl_vector_complex(np_array):
    size = len(np_array)
    data = (gsl_complex * size)() 
    for i in range(size):
        data[i].real = np_array[i].real
        data[i].imag = np_array[i].imag
    return gsl_vector_complex(size, data)

