import ctypes

def numpy_to_gsl_matrix_complex(np_array):
    from gsl import gsl_matrix_complex_alloc, gsl_matrix_complex_set
    rows = np_array.shape[0]
    cols = np_array.shape[1]
    A = gsl_matrix_complex_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl_matrix_complex_set(A, i, j, np_array[i, j])
    return A

def numpy_to_gsl_vector_complex(np_array):
    from gsl import gsl_vector_complex_alloc, gsl_vector_complex_set
    size = len(np_array)
    x = gsl_vector_complex_alloc(size)
    for i in range(size):
        gsl_vector_complex_set(x, i, np_array[i])
    return x

