class GSLIntegrationWorkspace:
    def __init__(self):
        self.workspace = gsl.gsl_integration_qagp_alloc()

    def free(self):
        gsl.gsl_integration_qagp_free(self.workspace)

def integrate_function(f, pts, epsabs, epsrel, limit, workspace):
    result = gsl.gsl_integration_qagp(f, pts[0], pts[1], epsabs, epsrel, limit, workspace)
    return result.result, abs(result.err)

def python_integrate(func, pts, epsabs, epsrel, limit, workspace):
    f = GSLFunction(func)
    workspace = GSLIntegrationWorkspace()
    result, error = integrate_function(f, pts, epsabs, epsrel, limit, workspace.workspace)
    workspace.free()
    return result, error

