import numpy as np
class GSLMatrix:
    def __init__(self, rows, cols):
        self._ptr = _allocate(rows, cols)
    def _allocate(self, rows, cols):
        return gsl.gsl_matrix_alloc(rows, cols)
    def free(self):
        gsl.gsl_matrix_free(self._ptr)
    def to_numpy(self):
        data = (gsl.gsl_matrix_get(self._ptr, i, j) for i in range(self._ptr.size1) for j in range(self._ptr.size2))
        return np.array(list(data)).reshape((self._ptr.size1, self._ptr.size2))

def list_to_ctypes_matrix(lst):
    rows = len(lst)
    cols = len(lst[0])
    matrix = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            matrix._ptr.set(i, j, lst[i][j])
    return matrix
def compute_covariance(jacobian, epsrel):
    jac_ptr = list_to_ctypes_matrix(jacobian)
    gsl_multifit_nlinear_covar = gsl.gsl_multifit_nlinear_covar
    # Define the function pointer and its arguments
    gsl_multifit_nlinear_covar.argtypes = [gsl.gsl_matrix, ctypes.c_float]
    gsl_multifit_nlinear_covar.restype = gsl.gsl_matrix
    cov_mat = gsl_multifit_nlinear_covar(jac_ptr, epsrel)
    return cov_mat.to_numpy()

