from ctypes import CDLL, c_int, c_double

GSLResult =  class GSLResult:
    def __init__(self, result, error):
        self.result = result
        self.error = error

def compute_bessel_Jn(n: c_int, x: c_double) -> GSLResult:
    libgslcblas = CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    libgsl = CDLL('/usr/local/gsl/lib/libgsl.so')
    result = libgsl.gsl_sf_bessel_Jn_e(n, x)
    error = libgsl.gsl_errno
    return GSLResult(result, error)

if __name__ == '__main__':
    try:
        n = int(input("Enter n: "))
        x = float(input("Enter x: "))
    except ValueError:
        print("Invalid input. Please enter integers and floating-point numbers.")
        exit()
    result = compute_bessel_Jn(n, x)
    print(f"J_{n}({x}) = {result.result}, Error: {result.error}")

