def gsl_linalg_pcholesky_decomp(matrix, perm):
    return _gsl_linalg_pcholesky_decomp(matrix, perm)
gsl.gsl_linalg_pcholesky_decomp = gsl_linalg_pcholesky_decomp

def _gsl_linalg_pcholesky_decomp(matrix, perm):
    return ctypes.cast(matrix, ctypes.POINTER(ctypes.c_double * (matrix.shape[0] * matrix.shape[1]))), ctypes.cast(perm, ctypes.POINTER(ctypes.c_int))

# Define GSL data structures
def create_gsl_matrix(rows, cols):
    return gsl.gsl_matrix_alloc(rows, cols)
def create_gsl_permutation(size):
    return gsl.gsl_permutation_alloc(size)

# Input matrix (symmetric positive-definite)
input_matrix = [[4, 2, -1], [2, 6, 3], [-1, 3, 3]]

