double_matrix = create_gsl_matrix(len(input_matrix), len(input_matrix[0]))
for i in range(len(input_matrix)):
    for j in range(len(input_matrix[0])):
        double_matrix.set(i, j, input_matrix[i][j])
perm = create_gsl_permutation(len(input_matrix))

# Perform LDLT decomposition
double_matrix_modified, perm_vector = gsl_linalg_pcholesky_decomp(double_matrix, perm)

